-- ****************************************************************************************************


declare
  cursor c1   is 
              select  'insert into ACTIVATOR.scoring_channel (id_scoring_plan, id_channel, date_update,user_update) values ('||sp.id||','||c.id||','||'SYSDATE,'||CHR(39)||'install'||CHR(39)||')' linea
                from  ACTIVATOR.channel c, ACTIVATOR.scoring_plan sp
               where  c.name in ('SUB_CM','DISTRIBUIDORES','Autoactivacion','CM_Dealer','Comunidad_GO','Corporativo','Fuerza_vd','Institucional','Pyme','Retail','Televentas','Tiendas_propias','Tienda_fvd','ABASTECIMIENTO','Ecommerce','CANALES_ESPECIALES')
                 and  sp.id_plan in ('775','776','777','778','779','780','781','782')
                 order by sp.id_plan, c.name; 
begin
    for r1 in c1 loop
            execute immediate r1.linea;
    end loop;
end;
/


COMMIT;

-- prompt hora fin script
select to_char(sysdate, 'dd/mm/yyyy hh24:mi:ss') hora, to_char (sysdate,'sssss') seg_past_midnight from dual;



